import sys
MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    p = [0] * (n + 2)
    p[0] = n + 1
    for k in range(n):
        x, y = data[1 + 2*k:3 + 2*k]
        p[x] = y
    dp = [0] * (n + 2)
    dp[0] = 1
    for b in range(1, n + 2):
        low = p[b]
        total = 0
        for a in range(b):
            high = p[a]
            if high <= low:
                continue
            vals = []
            minimum = n + 2
            for k in range(a + 1, b):
                v = p[k]
                if low < v < high:
                    if v < minimum:
                        minimum = v
                        vals.append(-v)
                    else:
                        vals.append(v)
            maximum = 0
            valid = True
            for v in reversed(vals):
                if v < 0:
                    v = -v
                    if v > maximum:
                        valid = False
                        break
                if v > maximum:
                    maximum = v
            if valid:
                total += dp[a]
        dp[b] = total % MOD
    print(dp[n + 1])

if __name__ == '__main__':
    solve()

