import sys

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]

    # bound[l][x]: smallest right endpoint of a condition targeting x
    # whose left endpoint is at least l. Endpoints on the right are exclusive.
    bound = [[n + 1] * n for _ in range(n)]
    for i in range(2, len(data), 3):
        l, r, x = data[i:i+3]
        if r < bound[l-1][x-1]:
            bound[l-1][x-1] = r

    for l in range(n-2, -1, -1):
        row, below = bound[l], bound[l+1]
        for k in range(n):
            if below[k] < row[k]:
                row[k] = below[k]

    inv = [0] * (n+1)
    inv[1] = 1
    for i in range(2, n+1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the valid ordering count divided by (r-l)!.
    dp = [[0] * (n+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][i] = 1

    for l in range(n-1, -1, -1):
        row = dp[l]
        limits = bound[l]
        for r in range(l+1, n+1):
            total = 0
            for k in range(l, r):
                if limits[k] > r:
                    total += row[k] * dp[k+1][r]
            row[r] = total * inv[r-l] % MOD

    ans = dp[0][n]
    for i in range(2, n+1):
        ans = ans * i % MOD
    print(ans)


if __name__ == '__main__':
    solve()

