import sys
MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, value in enumerate(data[1:]):
        p = 2
        while p * p <= value:
            if value % p == 0:
                e = 0
                while value % p == 0:
                    value //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = e
            p += 1
        if value > 1:
            if value not in factors:
                factors[value] = [0] * (n - 1)
            factors[value][i] = 1
    ans = 1
    for p, exponents in factors.items():
        total = sum(exponents)
        powers = [1] * (total + 1)
        for j in range(total):
            powers[j + 1] = powers[j] * p % MOD
        dp = [1]
        for i, a in enumerate(exponents, 1):
            if a == 0:
                dp = [v * powers[h] % MOD for h, v in enumerate(dp)]
                continue
            ndp = [0] * (len(dp) + a)
            for h, v in enumerate(dp):
                if not v:
                    continue
                ndp[h + a] = (ndp[h + a] + v * powers[h + a]) % MOD
                if h >= a:
                    ndp[h - a] = (ndp[h - a] + v * powers[h - a]) % MOD
                else:
                    ndp[0] = (ndp[0] + v * pow(p, i * (a - h), MOD)) % MOD
            dp = ndp
        ans = ans * (sum(dp) % MOD) % MOD
    print(ans)

if __name__ == '__main__':
    solve()

