import sys
import math

MOD = 998244353


def solve(a):
    limit = max(a)
    phi = list(range(limit + 1))
    for p in range(2, limit + 1):
        if phi[p] == p:
            for j in range(p, limit + 1, p):
                phi[j] -= phi[j] // p

    present = set(a)
    groups = {}
    for d in range(1, limit + 1):
        key = tuple(x for x in range(d, limit + 1, d) if x in present)
        if key:
            groups[key] = groups.get(key, 0) + phi[d]

    ds = [None] * (limit + 1)
    for x in present:
        ds[x] = []
    for key, p in groups.items():
        cell = [0, p]
        for x in key:
            ds[x].append(cell)
    del groups

    ans = 0
    w = 1
    out = []
    for start in range(0, len(a), 512):
        block = a[start:start + 512]
        vals = list(set(block))
        u = len(vals)
        total = sum(len(ds[x]) for x in block)
        if u * len(block) + 2 * sum(len(ds[x]) for x in vals) < total:
            index = {x: i for i, x in enumerate(vals)}
            rows = [[math.gcd(x, y) for y in vals] for x in vals]
            q = [sum(c[0] * c[1] for c in ds[x]) for x in vals]
            weights = [0] * u
            for x in block:
                j = index[x]
                ans = (ans * 2 + q[j]) % MOD
                out.append(str(ans))
                row = rows[j]
                for k in range(u):
                    q[k] += row[k] * w
                weights[j] += w
                w = w * 2 % MOD
            for x, t in zip(vals, weights):
                for c in ds[x]:
                    c[0] += t
        else:
            for x in block:
                q = 0
                for c in ds[x]:
                    v = c[0]
                    q += v * c[1]
                    c[0] = v + w
                ans = (ans * 2 + q) % MOD
                out.append(str(ans))
                w = w * 2 % MOD
    return '\n'.join(out)


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    print(solve(data[1:]))


if __name__ == '__main__':
    main()

