    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it)-1
            closed[e] = True
            queries.append((1, e))
        else:
            queries.append((2, next(it)-1, next(it)-1))
    inf = 10**18
    d = [[inf] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e, (a,b,c) in enumerate(edges):
        if not closed[e]:
            d[a][b] = d[b][a] = c
    rng = range(n)
    for k in rng:
        dk = d[k]
        for i in rng:
            di = d[i]
            v = di[k]
            if v == inf:
                continue
            for j in rng:
                z = v + dk[j]
                if z < di[j]:
                    di[j] = z
    ans = []
    for query in reversed(queries):
        if query[0] == 2:
            v = d[query[1]][query[2]]
            ans.append(str(v if v < inf else -1))
