import sys


def count_good(a, b, mod):
    if a > b:
        a, b = b, a
    bits = b.bit_length()
    mask = (1 << bits) - 1
    steps = [1 << (bits * j) for j in range(a)]
    dp = {0: 1}
    for _ in range(a * b - 1):
        nd = {}
        get = nd.get
        for state, value in dp.items():
            previous = b
            for j, step in enumerate(steps):
                height = (state >> (bits * j)) & mask
                if (height + 1 < previous if j == a - 1 else height < previous):
                    nxt = state + step
                    nd[nxt] = (get(nxt, 0) + value) % mod
                previous = height
        dp = nd
    return sum(dp.values()) % mod


def answer(a, b, mod):
    n = a * b - 1
    fact = 1
    for i in range(2, n + 1):
        fact = fact * i % mod
    hooks = 1
    for r in range(b):
        length = a if r < b - 1 else a - 1
        for c in range(length):
            below = b - r - 1 if c < a - 1 else b - r - 2
            hooks = hooks * (length - c + below) % mod
    tableaux = fact * pow(hooks, mod - 2, mod) % mod
    return tableaux * count_good(a, b, mod) % mod


def main():
    a, b, mod = map(int, sys.stdin.buffer.read().split())
    print(answer(a, b, mod))


