import sys
import heapq


def solve(n, m, a):
    if m > n:
        return 0
    if m == 1:
        return sum(max(0, v - p) for v, p in a)

    a.sort(reverse=True)
    profit = sum(max(0, v - p) for v, p in a)
    k = m - 1
    heap = []
    cost = 0
    ans = 0
    for v, p in a:
        profit -= max(0, v - p)
        x = p - 1
        if len(heap) < k:
            heapq.heappush(heap, -x)
            cost += x
        elif x < -heap[0]:
            cost += x + heapq.heapreplace(heap, -x)
        if len(heap) == k:
            ans = max(ans, profit - cost)
    return ans


