class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)
        dp = [0] * (length + 1)
        tight_ones = 0
        for pos, bit in enumerate(s):
            for ones in range(pos + 1, 0, -1):
                dp[ones] = (dp[ones] + dp[ones - 1]) % mod
            if bit == '1':
                dp[tight_ones] = (dp[tight_ones] + 1) % mod
                tight_ones += 1
        depth = [0] * (length + 1)
        for value in range(2, length + 1):
            depth[value] = depth[value.bit_count()] + 1
        return sum(dp[ones] for ones in range(1, length + 1)
                   if depth[ones] < k) % mod

