def brute(a):
    @lru_cache(None)
    def f(mask):
        if not mask: return 0
        bit=mask & -mask
        i=bit.bit_length()-1
        rest=mask^bit
        ans=f(rest)
        for j in range(i+1,len(a)):
            if rest>>j&1 and 2*a[i]<=a[j]:
                ans=max(ans,1+f(rest^(1<<j)))
        return ans
    return f((1<<len(a))-1)

