from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        w = m + 2
        size = (n + 2) * w
        g = [-1] * size
        for r, row in enumerate(grid, 1):
            g[r*w+1:r*w+m+1] = row
        answer = 0
        directions = ((1, 1), (1, -1), (-1, -1), (-1, 1))
        for d in range(4):
            dr, dc = directions[d]
            er, ec = directions[(d+1) % 4]
            step = dr*w + dc
            turn_step = er*w + ec
            suffix = [0] * size
            rows = range(n, 0, -1) if er == 1 else range(1, n+1)
            for r in rows:
                for k in range(r*w+1, r*w+m+1):
                    v = g[k]
                    target = 2 if v == 1 else 2-v
                    suffix[k] = 1 + suffix[k+turn_step] if g[k+turn_step] == target else 1
            prefix = [0] * size
            rows = range(1, n+1) if dr == 1 else range(n, 0, -1)
            for r in rows:
                for k in range(r*w+1, r*w+m+1):
                    v = g[k]
                    if v == 1:
                        p = 1
                    else:
                        p = prefix[k-step]
                        previous = g[k-step]
                        if p and v == (2 if previous == 1 else 2-previous):
                            p += 1
                        else:
                            p = 0
                    prefix[k] = p
                    if p:
                        candidate = p + suffix[k] - 1
                        if candidate > answer:
                            answer = candidate
        return answer

