from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        available = list(range(1, n + 1))
        odds, evens = (n + 1) // 2, n // 2
        answer = []
        previous = -1
        while available:
            m = len(available) - 1
            for i, value in enumerate(available):
                parity = value % 2
                if parity == previous:
                    continue
                o = odds - parity
                e = evens - (1 - parity)
                needed_odds = m // 2 + (m % 2 if parity == 0 else 0)
                if o != needed_odds:
                    continue
                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    available.pop(i)
                    odds, evens = o, e
                    previous = parity
                    break
            else:
                return []
        return answer

