        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, w in adj[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        free = [0] * n
        linked = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in adj[u]:
                if v == parent[u]:
                    continue
                base += free[v]
                gain = w + linked[v] - free[v]
                if gain > 0:
                    gains.append(gain)
            gains.sort(reverse=True)
            best = base + sum(gains[:k])
            free[u] = best
            linked[u] = best - (gains[k - 1] if len(gains) >= k else 0)

