def solve(h, w, rows):
    if any(row.count(b'A') & 1 for row in rows):
        return 0

    parent = [-1] * (h + w)
    parity = bytearray(h + w)
    col = bytearray(w)
    components = h + w

    for i, row in enumerate(rows):
        rp = 0
        for j, ch in enumerate(row):
            if ch == 65:
                rp ^= 1
                col[j] ^= 1
            else:
                x = i
                px = 0
                while parent[x] >= 0:
                    p = parent[x]
                    if parent[p] >= 0:
                        parity[x] ^= parity[p]
                        parent[x] = parent[p]
                    px ^= parity[x]
                    x = parent[x]

                y = h + j
                py = 0
                while parent[y] >= 0:
                    p = parent[y]
                    if parent[p] >= 0:
                        parity[y] ^= parity[p]
                        parent[y] = parent[p]
                    py ^= parity[y]
                    y = parent[y]

                need = px ^ py ^ rp ^ col[j] ^ 1
                if x == y:
                    if need:
                        return 0
                else:
                    if parent[x] > parent[y]:
                        x, y = y, x
                    parent[x] += parent[y]
                    parent[y] = x
                    parity[y] = need
                    components -= 1

    if any(col):
        return 0
    return pow(2, components, MOD)


