class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def occurrences(t):
            m = len(t)
            if m == 0:
                return range(len(s) + 1)
            if m > len(s):
                return []
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        a, b, c = p.split('*')
        starts = occurrences(a)
        middles = occurrences(b)
        ends = occurrences(c)
        j = k = 0
        best = len(s) + 1
        for start in starts:
            while j < len(middles) and middles[j] < start + len(a):
                j += 1
            if j == len(middles):
                break
            while k < len(ends) and ends[k] < middles[j] + len(b):
                k += 1
            if k == len(ends):
                break
            best = min(best, ends[k] + len(c) - start)
        return best if best <= len(s) else -1

