import heapq

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, W = data[:2]
    groups = [[] for _ in range(W + 1)]
    for i in range(2, len(data), 2):
        w, v = data[i], data[i + 1]
        if v > 1:
            groups[w].append(1 - v)
    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        heap = groups[w]
        if not heap:
            continue
        heapq.heapify(heap)
        gains = []
        for _ in range(W // w):
            gain = -heap[0]
            if gain <= 0:
                break
            gains.append(gain)
            heapq.heapreplace(heap, 2 - gain)
        if len(gains) < 8:
            for gain in gains:
                for cap in range(W, w - 1, -1):
                    candidate = dp[cap - w] + gain
                    if candidate > dp[cap]:
                        dp[cap] = candidate
        else:
            prefix = [0]
            for gain in gains:
                prefix.append(prefix[-1] + gain)
            q = len(gains)
            for r in range(w):
                old = dp[r::w]
                m = len(old)
                new = [0] * m
                def dc(left, right, low, high):
                    if left > right:
                        return
                    mid = (left + right) // 2
                    start = max(low, mid - q)
                    end = min(high, mid)
                    best = -1
                    opt = start
                    for j in range(start, end + 1):
                        candidate = old[j] + prefix[mid - j]
                        if candidate > best:
                            best = candidate
                            opt = j
                    new[mid] = best
                    dc(left, mid - 1, low, opt)
                    dc(mid + 1, right, opt, high)
                dc(0, m - 1, 0, m - 1)
                dp[r::w] = new
    print(dp[W])

