import random,time

def reconstruct(p):
    n = len(p)
    bit = [i & -i for i in range(n + 1)]
    ans = [0] * n
    top = 1 << (n.bit_length() - 1)
    for i in range(n, 0, -1):
        k = p[i - 1]
        idx = 0
        step = top
        while step:
            nxt = idx + step
            if nxt <= n and bit[nxt] < k:
                k -= bit[nxt]
                idx = nxt
            step >>= 1
        ans[idx] = i
        j = idx + 1
        while j <= n:
            bit[j] -= 1
            j += j & -j
    return ans

