def possible(s, t, k):
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    left = 0
    while left < min(n, m) and s[left] == t[left]:
        left += 1
    while n > left and m > left and s[n - 1] == t[m - 1]:
        n -= 1
        m -= 1
    s = s[left:n]
    t = t[left:m]
    n, m = len(s), len(t)
    if not n or not m:
        return max(n, m) <= k
    offset = k + 1
    prev = [-1] * (2 * k + 3)
    prev[offset] = 0
    for d in range(1, k + 1):
        curr = [-1] * len(prev)
        for diag in range(-d, d + 1):
            idx = offset + diag
            best = prev[idx]
            x = prev[idx]
            if x >= 0 and x < n and x - diag < m:
                best = x + 1
            x = prev[idx - 1]
            if x >= 0 and x < n and x + 1 > best:
                best = x + 1
            x = prev[idx + 1]
            if x >= 0 and x - diag - 1 < m and x > best:
                best = x
            if best < 0:
                continue
            y = best - diag
            while best < n and y < m and s[best] == t[y]:
                best += 1
                y += 1
            curr[idx] = best
            if best == n and y == m:
                return True
        prev = curr
    return False

