class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        dp = [1] * len(nums)
        masks = [(1 << (x + 1)) - 1 for x in nums]
        goals = [1 << x for x in nums]
        pending = sum(x != 0 for x in nums)
        if pending == 0:
            return 0
        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                if dp[i] & goals[i]:
                    continue
                dp[i] = (dp[i] | (dp[i] << val)) & masks[i]
                if dp[i] & goals[i]:
