from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        first = [False] * n
        answer = 0
        for i in range(1, (n - 1) // 2 + 1):
            if z[i] >= i:
                first[i] = True
                answer += n - 2 * i

        # Fix the middle length d. A backward equal-pair run measures
        # the common prefix of nums[i:] and nums[i + d:].
        for d in range(1, (n - 1) // 2 + 1):
            run = 0
            for i in range(n - d - 1, 0, -1):
                if nums[i] == nums[i + d]:
                    run += 1
                    if run >= d and not (i <= d and first[i]):
                        answer += 1
                else:
                    run = 0
        return answer

