from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        transitions = []
        for a, b in states:
            predecessors = [k for k, (x, y) in enumerate(states) if x != a and y != b]
            transitions.append((a, b, *predecessors))
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]
        for i in range(1, n // 2):
            left, right = cost[i], cost[n - 1 - i]
            dp = [left[a] + right[b] + min(dp[p], dp[q], dp[r])
                  for a, b, p, q, r in transitions]
        return min(dp)

