        present = {tuple(p) for p in points}
        best = -1
        for i, (x1, y1) in enumerate(points):
            for x2, y2 in points[i + 1:]:
                if x1 == x2 or y1 == y2:
                    continue
                if (x1, y2) not in present or (x2, y1) not in present:
                    continue
                left, right = min(x1, x2), max(x1, x2)
                bottom, top = min(y1, y2), max(y1, y2)
                count = sum(left <= x <= right and bottom <= y <= top for x, y in points)
                if count == 4:
                    best = max(best, (right - left) * (top - bottom))
        return best

